tool_input.command:
cd subjects/migrated/opus_5_5 && f=069_class-wp-image-editor-gd.php && perl -0pi -e '
s/is_resource\( \$(\w+) \)/self::is_gd_image( \$$1 )/g;
s/is_resource\( \$this->image \)/self::is_gd_image( \$this->image )/g;
s/list\( ([^)]*) \) =/[ $1 ] =/g;
s/ array\(\)/[]/g;
s/array\( (\$image[^)]*?) \)/[ $1 ]/g;
s/return array\((.*?)
		\);/return [$1
		];/s;
s/dirname\( \$filename \)/dirname( (string) \$filename )/;
s/(	protected \$image = false; // GD Resource
)/	protected \$image = false; // GD Resource (resource before PHP 8, GdImage object since PHP 8)

	/**
	 * Checks whether a value is a GD image (a GD resource on PHP < 8, a GdImage object on PHP 8+).
	 *
	 * \@param mixed \$image
	 * \@return bool
	 */
	private static function is_gd_image( \$image ): bool {
		return \$image instanceof GdImage || is_resource( \$image );
	}
/;
' $f && grep -n "is_gd_image\|\[\|list(" $f; cd -; tools/lint; tools/test 2>&1 | tail -4; tools/rector
